import cv2 as cv
import numpy as np
img = np.zeros((1024, 2048  , 3)  , np.uint8)
color=[0,0,0]
cx = 0
cy = 0
thickness = 1
drawing = False
drawing_shape = "rectangle"
class Shape:
    def __init__(self  , x , y , cx  , cy , color , thickness):
        self.x = x
        self.y = y
        self.cx = cx
        self.cy = cy
        self.color = color
        self.thickness = thickness
    def type(self):
        pass
    def show(self , img):
        pass
class Circle(Shape):
    def __init__(self  , x , y , cx  , cy , color , thickness):
        super().__init__( x , y , cx  , cy , color , thickness)
    def type(self):
        return ("circle")
    def show(self ,img):
        radius = int(((self.x - self.cx) ** 2 + (self.y - self.cy) ** 2) ** 0.5)
        cv.circle(
            img,
            (self.cx, self.cy),
            radius,
            self.color,
            self.thickness
        )


class Rectangle(Shape):
    def __init__(self, x, y, cx, cy, color, thickness):
        super().__init__(x, y, cx, cy, color, thickness)

    def type(self):
        return ("rectangle")

    def show(self, img):
        cv.rectangle(
            img,
            (self.cx, self.cy),
            (self.x , self.y),
            self.color,
            self.thickness
        )
def draw_circle(wert):
    global drawing_shape
    if  wert == 1:
      drawing_shape = "circle"
      cv.setTrackbarPos("Rectangle", "Window", 0)
def draw_rectangle(wert):
    global drawing_shape
    if wert == 1:
     drawing_shape = "rectangle"
     cv.setTrackbarPos("Circle" , "Window" , 0)

def set_red(wert):
    global img
    global color
    color[2] = wert
def set_blue(wert):
    global img
    global color
    color[0]= wert
def set_green(wert):
    global img
    global color
    color[1] = wert

def set_thickness(wert):
    global  thickness
    thickness = wert


def draw(event, x, y, flags, param):
    global cx, cy, drawing, img
    global color
    global thickness
    global drawing_shape
    # Start drawing
    if event == cv.EVENT_RBUTTONDOWN:
        cx = x
        cy = y
        drawing = True

    # Draw while moving the mouse
    elif event == cv.EVENT_MOUSEMOVE and drawing:
        # Restore the original image
        temp = img.copy()
        # Draw the rectangle preview
        if drawing_shape == "rectangle":

             rect = Rectangle(x,y,cx,cy,color ,thickness)
             rect.show(temp)
        else:
            circle= Circle(x,y,cx,cy,color ,thickness)
            circle.show(temp)

        cv.imshow("Window", temp)

    # Finish drawing
    elif event == cv.EVENT_RBUTTONUP:
        drawing = False
        if drawing_shape == "rectangle":

            rect = Rectangle(x, y, cx, cy, color, thickness)
            rect.show(img)
        else:
            circle = Circle(x, y, cx, cy, color, thickness)
            circle.show(img)

        cv.imshow("Window", img)


cv.namedWindow("Window")
cv.createTrackbar('Red:' , 'Window' , 0 , 255, set_red )
cv.createTrackbar('Blue:' , 'Window' , 0 , 255, set_blue )
cv.createTrackbar('Green:' , 'Window' , 0 , 255, set_green )
cv.createTrackbar('thickness:' , 'Window' , 1 , 10, set_thickness )# Onchange = function .
cv.createTrackbar('Circle' ,'Window' , 0 , 1 , draw_circle )
cv.createTrackbar('Rectangle' , 'Window',0 , 1 ,  draw_rectangle)
cv.setMouseCallback("Window", draw)
cv.imshow("Window", img)

while True:
    key = cv.waitKey(1)

    if key == ord('q'):  # ESC
        break

cv.destroyAllWindows()